async(page)=>{
 const checks=[],errors=[],base='E:/Dr.RouteFit/prototype/records/2026-10-24-driver-slide/';page.on('pageerror',e=>errors.push(e.message));const assert=(ok,msg)=>{if(!ok)throw Error(msg)};
 const role=r=>page.locator(`[data-role=${r}]`).first().click();const close=async()=>{await page.locator('[data-close]').first().click();if(await page.locator('#dialog').isVisible())await page.locator('[data-close]').first().click()};
 const fill=async values=>{for(const [k,v]of Object.entries(values)){const input=page.locator(`#action-form [name=${k}]`);if(typeof v==='boolean')await input.setChecked(v);else await input.fill(String(v))}};
 const submit=async()=>{await page.locator('#action-form [type=submit]').click();await page.locator('#dialog').waitFor({state:'hidden'})};
 const slide=async(fraction=1)=>{const track=await page.locator('.driver-slide').boundingBox(),handle=await page.locator('.driver-slide-handle').boundingBox();const travel=track.width-handle.width-8;await page.mouse.move(handle.x+handle.width/2,handle.y+handle.height/2);await page.mouse.down();await page.mouse.move(handle.x+handle.width/2+travel*fraction,handle.y+handle.height/2,{steps:12});await page.mouse.up()};
 const expected=async action=>assert(await page.locator('.driver-slide-handle').getAttribute('data-slide-action')===action,'wrong next step '+action);
 await page.goto('http://127.0.0.1:4173/prototype/');await page.reload();await page.setViewportSize({width:1440,height:1000});if(await page.locator('#exit-account-preview').count())await page.locator('#exit-account-preview').click();await role('dispatch');await page.locator('[data-action=qa]').first().click();await page.locator('[data-action=reset]').click();await submit();await role('dispatch');await page.locator('[data-dispatch-tab=orders]').click();await page.locator('[data-action=offer]').first().click();await page.locator('[name=vehicle][value=V01]').check();await submit();
 await role('driver');await page.setViewportSize({width:390,height:844});await expected('accept');
 let dock=await page.locator('.driver-dock').boundingBox(),nav=await page.locator('.driver-bottom').boundingBox(),track=await page.locator('.driver-slide').boundingBox();assert(dock.y>=0&&dock.y+dock.height<=845,'dock outside viewport');assert(track.y+track.height<=nav.y,'slider below menu');
 await page.locator('.driver-slide-handle').click();assert(!await page.locator('#dialog').isVisible(),'tap triggered action');await slide(.4);assert(!await page.locator('#dialog').isVisible(),'partial slide triggered action');await slide(-.3);assert(!await page.locator('#dialog').isVisible(),'reverse slide triggered action');
 const hb=await page.locator('.driver-slide-handle').boundingBox();await page.mouse.move(hb.x+24,hb.y+24);await page.mouse.down();await page.mouse.move(hb.x+90,hb.y+24);await page.locator('.driver-slide-handle').dispatchEvent('pointercancel');await page.mouse.up();assert(!await page.locator('#dialog').isVisible(),'cancelled gesture triggered action');
 await slide();assert(await page.locator('#dialog').isVisible(),'full swipe did not open');await close();assert(await page.locator('.driver-slide-handle').evaluate(el=>el.style.transform===''),'slide not reset on cancel');
 checks.push('390px操作区固定在菜单上方；点击、短滑、反向滑动不触发；完整右滑打开确认，取消后复位');
 await page.locator('.driver-slide-handle').focus();await page.keyboard.press('Enter');assert(await page.locator('#dialog').isVisible(),'keyboard unavailable');await submit();assert(await page.locator('.driver-slide').count()===0,'warehouse waiting still actionable');
 await role('warehouse');await page.locator('[data-action=prepare]').first().click();await fill({dimension:true,pattern:true,packaging:true,evidence:'DEMO-LOAD'});await submit();await role('driver');await expected('pickup');await slide();await page.locator('#action-form [type=submit]').click();await page.waitForFunction(()=>document.querySelector('#form-error')?.textContent.length>0);await fill({evidence:'DEMO-HANDOVER'});await submit();
 await expected('depart');await slide();await submit();await expected('report');await slide();await fill({proof:'DEMO-CASH'});await submit();await expected('deliver');await slide();await fill({receiver:'演示收货人',evidence:'DEMO-POD'});await submit();
 checks.push('接单→等待仓库→取货→出发→收款→签收右滑流程通过；交接缺凭证仍被原校验阻止');
 await role('finance');await page.locator('[data-action=verify]').first().click();await fill({evidence:'DEMO-CHECK'});await submit();await role('driver');await expected('remit');await page.locator('#toast.show').waitFor({state:'hidden'});await page.screenshot({path:base+'driver-action-mobile.png',fullPage:false});
 await page.locator('[data-driver-tab=orders]').click();assert(await page.locator('.driver-slide').count()===0,'action dock leaked into order list');await page.locator('[data-driver-tab=tasks]').click();await expected('remit');
 await page.setViewportSize({width:360,height:740});assert(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),'360px overflow');await page.evaluate(()=>window.scrollTo(0,document.body.scrollHeight));dock=await page.locator('.driver-dock').boundingBox();assert(dock.y+dock.height<=741,'dock moved offscreen after scroll');
 await page.setViewportSize({width:1440,height:1000});await page.screenshot({path:base+'driver-action-desktop.png',fullPage:false});await page.locator('[data-action=qa]').first().click();await page.locator('[data-mode=offline]').click();assert(await page.locator('.driver-slide-handle').isDisabled(),'offline remit enabled');await page.locator('[data-action=normal]').click();assert(!errors.length,errors.join('\n'));checks.push('订单列表不显示任务滑块；360px及桌面适配、滚动后操作区仍可用；无脚本错误');return {status:'PASS',checks,pageErrors:errors};
}
